import pandas as pd,numpy as np
def load(f):
    d=pd.read_csv(f); return d
def arx(files,lags,ylab):
    rows=[];ys=[]
    for f in files:
        d=load(f)
        P=d.active_power_pu.values;Q=d.reactive_power_pu.values;V=d.voltage_pu.values;th=d.bus_angle_rad.values;S=d.voltage_setpoint_pu.values
        n=len(d);L=max(lags)
        for k in range(L,n):
            r=[1.0]
            for l in lags:
                r+= [P[k-l],Q[k-l],V[k-l]-1,th[k-l],S[k-l]-1]
            rows.append(r); ys.append((P[k],Q[k]))
    return np.array(rows),np.array(ys)
files=['train/A3_vref_op1.csv']
for lags in [[1],[1,2,5,10,20,50]]:
    X,Y=arx(files,lags,None)
    b=np.linalg.lstsq(X,Y,rcond=None)[0]
    res=Y-X@b
    print(lags,'res std',res.std(0), 'Qstd',Y[:,1].std(),'Pstd',Y[:,0].std())
